"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Check, Zap } from "@/components/ui/icons";

// Selection Card: generated by UIX from the design system. Same variants and sizes as the Figma component.

const selectionCardVariants = cva(
  "relative flex cursor-pointer items-start gap-3 p-4 bg-surface border border-line-default hover:border-line-strong transition-colors has-[:checked]:border-2 has-[:checked]:border-line-brand has-[:checked]:bg-brand-subtle has-[:focus-visible]:ring-3 has-[:focus-visible]:ring-line-focus has-[:disabled]:cursor-not-allowed has-[:disabled]:bg-subtle has-[:disabled]:text-fg-disabled rounded-xl",
  {
    variants: {
      type: {
        radio: "",
        checkbox: "",
      },
    },
    defaultVariants: {
      type: "radio",
    },
  },
);

export interface SelectionCardProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "type" | "size" | "title" | "prefix">,
    VariantProps<typeof selectionCardVariants> {
  title: React.ReactNode;
  description?: React.ReactNode;
  /** Price or other fact under the description. */
  price?: React.ReactNode;
  /** Replaces the default icon in the round badge. */
  icon?: React.ReactNode;
}

const SelectionCard = React.forwardRef<HTMLInputElement, SelectionCardProps>(
  ({ className, type, title, description, price, icon, ...props }, ref) => (
    <label data-slot="selection-card" data-kind="surface" className={cn(selectionCardVariants({ type }), className)}>
      <input ref={ref} type={type === "checkbox" ? "checkbox" : "radio"} className="peer sr-only" {...props} />
      <span aria-hidden className="inline-flex shrink-0 items-center justify-center rounded-full size-10 bg-brand-subtle text-icon-brand [&_svg]:size-5 peer-checked:bg-surface">{icon ?? <Zap />}</span>
      <span className="flex min-w-0 flex-1 flex-col gap-0-5">
        <span className="text-label-large text-fg-primary">{title}</span>
        {description ? <span className="text-body-small text-fg-secondary">{description}</span> : null}
        {price ? <span className="text-label-medium text-fg-primary">{price}</span> : null}
      </span>
      <span aria-hidden className={cn("ml-auto inline-flex shrink-0 items-center justify-center border size-5 border-line-strong bg-surface peer-checked:border-transparent peer-checked:bg-brand peer-disabled:bg-disabled [&_svg]:size-[14px] [&_svg]:text-fg-on-brand [&_svg]:opacity-0 peer-checked:[&_svg]:opacity-100", type === "checkbox" ? "rounded-sm" : "rounded-full")}>
        <Check />
      </span>
    </label>
  ),
);
SelectionCard.displayName = "SelectionCard";

export { SelectionCard, selectionCardVariants };
